/* idltest_echo without waiting: the request, with the caller's txid (not 0).
 * The reply comes on ch: idl_reply_read, then idltest_echo_result. */
static inline status_t idltest_echo_send(handle_t ch, uint32_t idl_txid, uint32_t value)
{
    struct idltest_echo_req idl_q;
    if (!idl_txid)
        return ERR_INVALID_ARGS;
    idl_q.txid = idl_txid;
    idl_q.ordinal = IDLTEST_ECHO;
    idl_q.value = value;
    return drv_channel_write(ch, &idl_q, sizeof(idl_q), NULL, 0);
}

/* The status and results of a reply to idltest_echo_send (read with
 * idl_reply_read). The reply's handles are taken in every case: moved to
 * the results, or closed (on a failure, or for a NULL result). */
static inline status_t idltest_echo_result(const void *idl_rep, struct idl_msg *idl_m, uint32_t *out_value)
{
    const struct idltest_echo_rep *idl_r = (const struct idltest_echo_rep *)idl_rep;
    status_t idl_st = idl_rep_status(idl_rep, idl_m->n, sizeof(*idl_r));
    if (idl_st == OK && idl_m->nh != 0)
        idl_st = ERR_INTERNAL;
    if (idl_st != OK) {
        idl_msg_drop(idl_m);
        return idl_st;
    }
    idl_m->nh = 0;
    if (out_value)
        *out_value = idl_r->value;
    return OK;
}

